mapper.select:
SELECT COUNT(*)
FROM ${table}
WHERE deleted_at IS NOT NULL
  AND deleted_at <= #{cutoff}
  AND archived_at IS NULL

mapper.update:
UPDATE archive_records
SET status = 'COPIED', error_message = NULL
WHERE source_table = #{table}
  AND source_id = #{sourceId}
  AND deleted_at = #{deletedAt}
  AND status = 'PENDING'

UPDATE ${table}
SET archived_at = NOW()
WHERE

    ${key} = #{values[${index}]}

  AND archived_at IS NULL

mapper.delete:
DELETE FROM ${table}
WHERE

    ${key} = #{values[${index}]}

  AND archived_at IS NOT NULL

mapper.update:
UPDATE archive_records
SET status = 'COMPLETED', archived_at = NOW(), error_message = NULL
WHERE source_table = #{table}
  AND source_id = #{sourceId}
  AND deleted_at = #{deletedAt}
  AND status = 'COPIED'

UPDATE archive_records
SET status = 'FAILED', archived_at = NULL, error_message = #{message}
WHERE source_table = #{table}
  AND source_id = #{sourceId}
  AND deleted_at = #{deletedAt}
  AND status <> 'COMPLETED'
